<?php
$loans = active_loans((int)$user['id']);
$requests = query('SELECT r.*,b.title,b.author,b.icon FROM requests r JOIN books b ON b.id=r.book_id WHERE r.user_id=? ORDER BY r.id DESC LIMIT 50',[$user['id']])->fetchAll();
$history = query('SELECT l.*,b.title,b.author,b.icon FROM loans l JOIN books b ON b.id=l.book_id WHERE l.user_id=? AND l.returned_at IS NOT NULL ORDER BY l.returned_at DESC LIMIT 50',[$user['id']])->fetchAll();
$statuses = ['pending'=>'Ожидает выдачи','fulfilled'=>'Книга выдана','rejected'=>'Отклонена','cancelled'=>'Отменена'];
?>
<h1 class="sr-only">Мои книги</h1>
<div class="loan-list"><?php foreach ($loans as $loan): $days=overdue_days($loan['due_date']); ?>
<article class="loan-row <?= $days ? 'overdue' : '' ?>"><span class="book-icon"><?= icon($loan['icon']) ?></span><div class="loan-content"><h2><?= e($loan['title']) ?></h2><p class="muted"><?= e($loan['author']) ?></p><p class="dates">▣ Взята: <?= format_date($loan['issued_at']) ?> <span>▣ Вернуть до: <?= format_date($loan['due_date']) ?></span></p></div><span class="badge <?= $days ? 'danger' : 'success-badge' ?>"><?= $days ? '◷ Просрочено '.$days.' дн.' : '◷ В срок' ?></span></article>
<?php endforeach; ?></div>
<?php if (!$loans): ?><section class="panel empty"><span class="empty-icon">📖</span><h2>У вас пока нет выданных книг</h2><p class="muted">Выберите книгу в каталоге и отправьте заявку.</p><a class="button primary" href="index.php">Перейти в каталог</a></section><?php endif; ?>
<?php if ($requests): ?><section class="panel section-gap"><h2>Мои заявки</h2><p class="muted subtitle">Последние 50 заявок. Заявка не резервирует экземпляр до оформления выдачи.</p><div class="request-list"><?php foreach ($requests as $request): ?><div class="request-row"><span class="mini-icon"><?= icon($request['icon']) ?></span><div class="grow"><strong><?= e($request['title']) ?></strong><p class="muted"><?= format_date($request['created_at']) ?> · <?= $statuses[$request['status']] ?></p></div><?php if ($request['status']==='pending'): ?><form method="post"><?= csrf_input() ?><input type="hidden" name="action" value="cancel_request"><input type="hidden" name="request_id" value="<?= $request['id'] ?>"><button class="button small outline">Отменить</button></form><?php endif; ?></div><?php endforeach; ?></div></section><?php endif; ?>
<?php if ($history): ?><section class="panel section-gap"><h2>История чтения</h2><p class="muted subtitle">Последние 50 возвращённых книг</p><?php foreach ($history as $loan): ?><div class="request-row"><span class="mini-icon"><?= icon($loan['icon']) ?></span><div><strong><?= e($loan['title']) ?></strong><p class="muted">Выдана: <?= format_date($loan['issued_at']) ?> · Возвращена: <?= format_date($loan['returned_at']) ?></p></div><span class="badge success-badge">Возвращена</span></div><?php endforeach; ?></section><?php endif; ?>
